const INK="#0a1a6b",ACC="#ff6b3d",SUN="#ffd23f",BLU="#2b55ff",WH="#fff",CRM="#fff4de",LBL="#dfe7ff";
const tx=(x,y,lines,o={})=>{const L=[].concat(lines),fs=o.fs||20,lh=fs*1.15,y0=y-(L.length-1)*lh/2;
 return `<text x="${x}" y="${y0}" text-anchor="${o.a||"middle"}" dominant-baseline="middle" font-size="${fs}" font-weight="${o.w||700}" fill="${o.c||INK}">${L.map((l,i)=>`<tspan x="${x}" dy="${i?lh:0}">${l}</tspan>`).join("")}</text>`};
const bx=(x,y,w,h,f,lines,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??16}" fill="${f}" stroke="${INK}" stroke-width="3"/>`+(lines?tx(x+w/2,y+h/2,lines,o):"");
const ci=(x,y,r,f,lines,o={})=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" stroke="${INK}" stroke-width="3"/>`+(lines?tx(x,y,lines,o):"");
const ar=(x1,y1,x2,y2,c=INK)=>{const a=Math.atan2(y2-y1,x2-x1),h=13,p=(d)=>`${(x2-h*Math.cos(a+d)).toFixed(1)},${(y2-h*Math.sin(a+d)).toFixed(1)}`;
 return `<path d="M${x1} ${y1}L${x2} ${y2}" stroke="${c}" stroke-width="3.5" stroke-linecap="round" fill="none"/><polygon points="${x2},${y2} ${p(.45)} ${p(-.45)}" fill="${c}"/>`};
const svg=(h,label,body)=>`<svg viewBox="0 0 640 ${h}" role="img" aria-label="${label}" font-family="DM Sans, Inter, Arial, sans-serif">${body}</svg>`;
const ring=(cx,cy,r,n,labels,fills,o={})=>{let s="";const P=labels.map((_,i)=>{const a=-Math.PI/2+i/n*Math.PI*2;return[cx+Math.cos(a)*r,cy+Math.sin(a)*r]});
 P.forEach((p,i)=>{const q=P[(i+1)%n],a=Math.atan2(q[1]-p[1],q[0]-p[0]),d=Math.hypot(q[0]-p[0],q[1]-p[1]),m=o.nr||52;
  s+=ar(+(p[0]+Math.cos(a)*m).toFixed(1),+(p[1]+Math.sin(a)*m).toFixed(1),+(p[0]+Math.cos(a)*(d-m-4)).toFixed(1),+(p[1]+Math.sin(a)*(d-m-4)).toFixed(1))});
 P.forEach((p,i)=>{s+=o.box?bx(p[0]-o.box[0]/2,p[1]-o.box[1]/2,o.box[0],o.box[1],fills[i%fills.length],labels[i],{fs:o.fs||19}):ci(p[0],p[1],o.nr||52,fills[i%fills.length],labels[i],{fs:o.fs||18})});return s};
